mapper.select:
select mn.*, pre.p_name as projectName,indicator.name as indicatorName,tc.type_name as infoTypeName from pre_project_solution_info mn left join pre_project pre on mn.project_id = pre.P_ID left join znpj_indicator_info_type_config tc on mn.info_type = tc.type_code left join znpj_indicator indicator on mn.indicator_id = indicator.id and indicator.indicator_version_id = mn.indicator_version_id and indicator.status = 1 and indicator.del_flag = 1
pre.p_name like concat('%',#{params.projectName},'%')
and mn.project_id = #{params.projectId}
and mn.type_code =#{params.infoType}
and indicator.name like concat('%',#{params.indicatorName},'%')
and mn.create_uid = #{params.createUid}
